const items = $input.all();
const resultado = [];

const regiones = $items("Code in JavaScript Regiones productoras");

for (const item of items) {

  const clima = item.json;

  if (!clima.daily?.time) {
    continue;
  }

  // Buscar la región más cercana a las coordenadas
  let regionEncontrada = null;
  let menorDistancia = Infinity;

  for (const r of regiones) {

    const region = r.json;

    const distancia =
      Math.abs(Number(clima.latitude) - Number(region.latitud)) +
      Math.abs(Number(clima.longitude) - Number(region.longitud));

    if (distancia < menorDistancia) {
      menorDistancia = distancia;
      regionEncontrada = region;
    }
  }

  if (!regionEncontrada) {
    continue;
  }

  // Crear una fila por cada día histórico
  for (let i = 0; i < clima.daily.time.length; i++) {

    resultado.push({
      json: {

        fecha:
          clima.daily.time[i],

        ubicacion:
          regionEncontrada.region,

        region_id:
          regionEncontrada.region_id,

        ciudad_referencia:
          regionEncontrada.ciudad_referencia,

        latitud:
          Number(regionEncontrada.latitud),

        longitud:
          Number(regionEncontrada.longitud),

        temperatura:
          clima.daily.temperature_2m_mean?.[i] ?? null,

        precipitacion:
          clima.daily.precipitation_sum?.[i] ?? null,

        humedad:
          clima.daily.relative_humidity_2m_mean?.[i] ?? null,

        evapotranspiracion:
          clima.daily.et0_fao_evapotranspiration?.[i] ?? null,

        tipo_dato:
          "historico"
      }
    });
  }
}

return resultado;

