const items = $input.all();
const results = [];
const vistos = new Set();

const unidades = [
  "Atado Grande",
  "Cajon Chico",
  "Cajón Chico",
  "Saco Chico",
  "Kilogramo",
  "Atado",
  "Cajon",
  "Cajón",
  "Saco",
  "Bolsa",
  "Mano",
  "Docena",
  "Ciento",
  "Paquete",
  "Unidad"
];

// =====================================
// FECHA ACTUAL DEL LOOP
// =====================================
let fechaObjetivo = null;

try {
  fechaObjetivo =
    $("Loop Over Items").item.json.fecha_objetivo;
} catch (e) {}

function numero(valor) {

  if (
    valor === undefined ||
    valor === null ||
    valor === "" ||
    valor === ":"
  ) {
    return null;
  }

  const n = Number(
    String(valor)
      .replace(",", ".")
      .trim()
  );

  return Number.isFinite(n)
    ? n
    : null;
}

function esFilaNumerica(linea) {

  const tokens =
    linea.trim().split(/\s+/);

  return tokens.every(token =>
    token === ":" ||
    /^-?\d+(?:[.,]\d+)?$/.test(token)
  );
}

function agregarRegistro({
  producto,
  unidad,
  lineaVolumen,
  lineaPrecios,
  fecha
}) {

  if (!producto || !unidad) {
    return;
  }

  const volumenes =
    lineaVolumen
      .split(/\s+/)
      .map(numero);

  const precios =
    lineaPrecios
      .split(/\s+/)
      .map(numero);

  if (precios.length < 3) {
    return;
  }

  const equivalenciaKg =
    precios[0];

  const precioHoy =
    precios[2];

  if (precioHoy === null) {
    return;
  }

  const volumenHoy =
    volumenes.length >= 2
      ? volumenes[1]
      : null;

  // Evitar duplicados dentro del mismo PDF
  const clave =
    `${fecha}|${producto}|${unidad}`;

  if (vistos.has(clave)) {
    return;
  }

  vistos.add(clave);

  results.push({
    json: {

      fecha,

      producto:
        producto.trim(),

      mercado:
        "GMML",

      precio:
        precioHoy,

      volumen_t:
        volumenHoy,

      volumen_kg:
        volumenHoy !== null
          ? volumenHoy * 1000
          : null,

      unidad,

      equivalencia_kg:
        equivalenciaKg
    }
  });
}

// =====================================
// PROCESAR PDFs
// =====================================

for (const item of items) {

  const text =
    item.json.text ?? "";

  if (!text.trim()) {
    continue;
  }

  let fechaHistorica =
    fechaObjetivo;

  if (
    !fechaHistorica &&
    item.json.info?.CreationDate
  ) {

    const raw =
      item.json.info.CreationDate;

    const year =
      raw.substring(2, 6);

    const month =
      raw.substring(6, 8);

    const day =
      raw.substring(8, 10);

    fechaHistorica =
      `${year}-${month}-${day}`;
  }

  const lines = text
    .split(/\r?\n/)
    .map(x =>
      x.replace(/\s+/g, " ").trim()
    )
    .filter(Boolean);

  // =====================================
  // FORMATO 1:
  //
  // Acelga
  // 1 : :
  // Atado
  // 1.00 4.38 4.50 4.52
  // =====================================

  for (let i = 0; i < lines.length; i++) {

    const unidad =
      unidades.find(
        u =>
          lines[i].toLowerCase() ===
          u.toLowerCase()
      );

    if (!unidad) {
      continue;
    }

    if (
      i >= 2 &&
      i + 1 < lines.length &&
      esFilaNumerica(lines[i - 1]) &&
      esFilaNumerica(lines[i + 1])
    ) {

      agregarRegistro({
        producto:
          lines[i - 2],

        lineaVolumen:
          lines[i - 1],

        unidad,

        lineaPrecios:
          lines[i + 1],

        fecha:
          fechaHistorica
      });
    }
  }

  // =====================================
  // FORMATO 2:
  // TODO EN UNA MISMA LÍNEA
  // =====================================

  for (const linea of lines) {

    const unidad =
      unidades.find(u =>
        linea.includes(` ${u} `)
      );

    if (!unidad) {
      continue;
    }

    const posicionUnidad =
      linea.indexOf(` ${unidad} `);

    if (posicionUnidad === -1) {
      continue;
    }

    const izquierda =
      linea
        .slice(0, posicionUnidad)
        .trim();

    const derecha =
      linea
        .slice(
          posicionUnidad +
          unidad.length + 2
        )
        .trim();

    const datosPrecio =
      derecha
        .split(/\s+/)
        .map(numero);

    if (datosPrecio.length < 3) {
      continue;
    }

    const tokens =
      izquierda.split(/\s+/);

    const volumenesInvertidos = [];

    while (tokens.length > 0) {

      const ultimo =
        tokens[tokens.length - 1];

      if (
        ultimo === ":" ||
        /^-?\d+(?:[.,]\d+)?$/.test(ultimo)
      ) {

        volumenesInvertidos.push(
          tokens.pop()
        );

      } else {
        break;
      }
    }

    const producto =
      tokens.join(" ").trim();

    const lineaVolumen =
      volumenesInvertidos
        .reverse()
        .join(" ");

    agregarRegistro({

      producto,

      unidad,

      lineaVolumen,

      lineaPrecios:
        derecha,

      fecha:
        fechaHistorica
    });
  }
}

return results;

