const text = $json.text ?? "";

if (!text.trim()) {
  return [];
}

const TAMANO = 1200;
const SOLAPAMIENTO = 200;

const chunks = [];

let inicio = 0;

while (inicio < text.length) {

  const fin = Math.min(inicio + TAMANO, text.length);

  const fragmento = text
    .slice(inicio, fin)
    .trim();

  if (fragmento) {
    chunks.push(fragmento);
  }

  if (fin >= text.length) {
    break;
  }

  inicio = fin - SOLAPAMIENTO;
}

return [{
  json: {
    chunks,
    cantidad_chunks: chunks.length,
    fuente: "MIDAGRI",
    tipo_documento: "boletin_diario",
    fecha: $("Loop Over Items").item.json.fecha_objetivo
  }
}];

const respuesta = $json;

const origen = $("Code - Preparar chunks Jina").item.json;

const chunks = origen.chunks ?? [];
const embeddings = respuesta.data ?? [];

const resultado = [];

for (let i = 0; i < embeddings.length; i++) {

  if (!chunks[i] || !embeddings[i]?.embedding) {
    continue;
  }

  resultado.push({
    json: {
      texto: chunks[i],

      embedding: embeddings[i].embedding,

      metadata: {
        fuente: "MIDAGRI",
        tipo_documento: "boletin_diario",
        fecha: origen.fecha,
        chunk: i + 1,
        total_chunks: chunks.length,
        modelo_embedding: "jina-embeddings-v3",
        dimensiones: 384
      }
    }
  });
}

return resultado;
